command -v python3>/dev/null||exit 127;Q=${QUERY:-${1:-}};[ -n "$Q" ]||{ echo "QUERY required" >&2;exit 2;};python3 -c 'import sys,re,json,html,urllib.parse as P,urllib.request as U,functools;q,s,L=sys.argv[1],sys.argv[2],int(sys.argv[3]);z=("site:"+s+" " if s else "")+q;u="https://html.duckduckgo.com/html/?q="+P.quote_plus(z);R=[];exec("try:\n t=U.urlopen(U.Request(u,headers={\x27User-Agent\x27:\x27Mozilla/5.0\x27}),timeout=12).read().decode(\x27utf8\x27,\x27ignore\x27)\nexcept Exception as e:\n print(json.dumps({\x27query\x27:q,\x27error\x27:str(e)},ensure_ascii=False,separators=(\x27,\x27,\x27:\x27)));sys.exit(1)\nfor h in re.findall(r\x27href=\\\"([^\\\"]+)\\\"\x27,t):\n v=html.unescape(h)\n if \x27uddg=\x27 in v:v=P.parse_qs(P.urlparse(v).query).get(\x27uddg\x27,[v])[0]\n if v.startswith(\x27http\x27) and (not s or s in v) and v not in R:R.append(v)\n if len(R)>=L:break");g=functools.reduce(lambda a,b:a*257+b+1,q.encode(),1);print(json.dumps({"query":q,"GQUERY":str(g),"results":R},ensure_ascii=False,separators=(",",":")))' "$Q" "${SITE:-}" "${LIMIT:-8}"